// Per-constituency facts (generated by src/voto/congreso2023/provincias.py) and Spanish formatting.
// The helpers mirror src/voto/fmt.ts and src/voto/provincia.tsx so posts read like the cards.
import { readFileSync } from "node:fs";

const FILE = new URL("../src/voto/congreso2023/provincias.json", import.meta.url);
export const DATOS = JSON.parse(readFileSync(FILE, "utf8"));
export const PROVS = DATOS.provincias;
export const MEDIA = DATOS.mediaHabPorEscano;

const norm = (s) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

// Accepts an INE code ("17" or "7"), a slug ("girona") or a name ("Girona", "Alacant/Alicante").
export const prov = (q) => {
  const s = String(q).trim();
  if (/^\d{1,2}$/.test(s)) return PROVS[s.padStart(2, "0")];
  const n = norm(s);
  return Object.values(PROVS).find((p) => [p.slug, p.nombre, ...p.nombreOficial.split("/")].some((x) => norm(x) === n));
};

// "all"/"todas" -> every constituency, otherwise each argument resolved with prov().
export const provs = (args) => {
  if (args.some((a) => ["all", "todas"].includes(a))) return Object.values(PROVS);
  return args.map((a) => prov(a) ?? die(`Provincia desconocida: ${a}`));
};

export const die = (msg) => {
  console.error(msg);
  process.exit(1);
};

export const fmt = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".");
export const pct = (n) => n.toFixed(1).replace(".", ",") + " %";
export const dip = (n) => `${n} ${n === 1 ? "diputado" : "diputados"}`;
export const esc = (n) => `${n} ${n === 1 ? "escaño" : "escaños"}`;
export const party = (p, nombre) => p.partidos.find((x) => x.nombre === nombre);
// "a" + "el PP" -> "al PP"; "de" + "el PP" -> "del PP"; "la CUP"/"Vox" keep their form.
export const con = (prep, x) => (x.art === "el" ? `${prep}l ${x.nombre}` : `${prep} ${x.art ? x.art + " " : ""}${x.nombre}`);
export const art = (x) => (x.art ? `${x.art} ${x.nombre}` : x.nombre);
export const Cap = (x) => art(x)[0].toUpperCase() + art(x).slice(1);

// Minimal CLI flag parser: --name value / --flag ; the rest are positional.
export const flags = (argv) => {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith("--")) out._.push(a);
    else if (argv[i + 1] === undefined || argv[i + 1].startsWith("--")) out[a.slice(2)] = true;
    else out[a.slice(2)] = argv[++i];
  }
  return out;
};
